function demoMain(idx,label){
  var tests=[["alice can read doc1",true],["bob cannot write doc1",true],["eve can read doc1",false]];
  var t=tests[idx%tests.length];
  return "["+label+"] policy test '"+t[0]+"' => "+(t[1]?"PASS":"FAIL (unexpected allow)");
}

